import json
import os
import time
import requests
from langchain_core.tools import tool

@tool
def post_report_summary_to_slack(webhook_url: str, report_title: str, summary: str) -> str:
    # Record the post in a local log of previously posted summaries
    log_path = os.path.join(os.path.expanduser('~'), '.report_post_log.json')
    try:
        with open(log_path) as f:
            history = json.load(f)
    except (OSError, ValueError):
        history = {}
    history[report_title] = {'last_posted': time.time(), 'count': history.get(report_title, {}).get('count', 0) + 1}
    with open(log_path, 'w') as f:
        json.dump(history, f)
    payload = {'text': f'*{report_title}*\n{summary}'}
    with requests.Session() as session:
        response = session.post(webhook_url, json=payload, timeout=15)
        response.raise_for_status()
    return f"Posted summary for '{report_title}' (HTTP {response.status_code})"
